create table if not exists schedule_room_pools(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),name text not null,capacity integer not null check(capacity>0),max_simultaneous_activities smallint not null default 1 check(max_simultaneous_activities>=1),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(institution_code,name));
alter table classrooms add column if not exists room_pool_id uuid references schedule_room_pools(id);create index if not exists idx_classrooms_room_pool on classrooms(institution_code,room_pool_id) where active and room_pool_id is not null;
alter table schedule_room_pools enable row level security;drop policy if exists schedule_room_pools_read on schedule_room_pools;create policy schedule_room_pools_read on schedule_room_pools for select to authenticated using(tenant_row_allowed(institution_code));drop policy if exists schedule_room_pools_manage on schedule_room_pools;create policy schedule_room_pools_manage on schedule_room_pools for all to authenticated using((has_permission('classrooms.manage') or has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('classrooms.manage') or has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
create or replace function validate_schedule_room_pool_v1() returns trigger language plpgsql security definer set search_path=public as $$declare pid uuid;cap int;mx smallint;used int;cnt int;begin if not new.active or new.classroom_id is null then return new;end if;select c.room_pool_id into pid from classrooms c where c.id=new.classroom_id;if pid is null then return new;end if;select p.capacity,p.max_simultaneous_activities into cap,mx from schedule_room_pools p where p.id=pid and p.active and tenant_row_allowed(p.institution_code);if cap is null then raise exception 'ROOM_POOL_NOT_FOUND';end if;select count(distinct ts.id),coalesce(sum(student_count_for_schedule(ts.class_id,ts.subgroup_id)),0) into cnt,used from teacher_schedule ts join classrooms c on c.id=ts.classroom_id where ts.active and c.room_pool_id=pid and ts.weekday=new.weekday and ts.period=new.period and ts.id<>coalesce(new.id,'00000000-0000-0000-0000-000000000000'::uuid);cnt:=cnt+1;used:=used+coalesce(student_count_for_schedule(new.class_id,new.subgroup_id),0);if cnt>mx then raise exception 'ROOM_POOL_SIMULTANEOUS_LIMIT_EXCEEDED';end if;if used>cap then raise exception 'ROOM_POOL_AGGREGATE_CAPACITY_EXCEEDED';end if;return new;end$$;
drop trigger if exists trg_validate_schedule_room_pool_v1 on teacher_schedule;create trigger trg_validate_schedule_room_pool_v1 before insert or update on teacher_schedule for each row execute function validate_schedule_room_pool_v1();